WITH agg AS ( SELECT c.c_customer_id, t.t_hour, t.t_meal_time, COUNT(cs.cs_order_number) AS orders, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_net_paid) AS total_net_paid, AVG(CASE WHEN cs.cs_ext_sales_price = 0 THEN 0 ELSE cs.cs_ext_discount_amt / cs.cs_ext_sales_price END) AS avg_discount_rate, CASE WHEN SUM(cs.cs_net_profit) >= 10000 THEN 'HIGH' WHEN SUM(cs.cs_net_profit) >= 5000 THEN 'MEDIUM' ELSE 'LOW' END AS profit_category, COALESCE(wp_counts.web_page_cnt, 0) AS web_page_cnt FROM catalog_sales cs JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk LEFT JOIN (SELECT wp_customer_sk, COUNT(*) AS web_page_cnt FROM web_page GROUP BY wp_customer_sk) wp_counts ON c.c_customer_sk = wp_counts.wp_customer_sk WHERE cs.cs_sold_time_sk IS NOT NULL GROUP BY c.c_customer_id, t.t_hour, t.t_meal_time, wp_counts.web_page_cnt HAVING COUNT(cs.cs_order_number) >= 5 ) SELECT a.c_customer_id, a.t_hour, a.t_meal_time, a.orders, a.total_net_profit, a.total_net_paid, a.avg_discount_rate, a.profit_category, a.web_page_cnt, RANK() OVER (PARTITION BY a.t_hour ORDER BY a.total_net_profit DESC) AS profit_rank_within_hour FROM agg a ORDER BY a.t_hour, profit_rank_within_hour LIMIT 10
